"""Reproducible frontend revision only, over previously produced source arrays."""
from pathlib import Path
import re

root = Path(__file__).resolve().parent
s = (root.parent / 'offline_dashboard_source/app.js').read_text()
s = s.replace("const PAGE_GENES = 30, TABLE_ROWS = 100, STORAGE = 'SATB2_OFFLINE_SETTINGS_V1';", "const TABLE_ROWS = 100, BOX_PAGE = 6, STORAGE = 'SATB2_OFFLINE_SETTINGS_V2';")
s = s.replace('const value=await boundedDecode(encoded);cache.set(id,value);', 'const value=await boundedDecode(encoded);if(!customLoader&&global.SATB2_SHARDS)delete global.SATB2_SHARDS[id];cache.set(id,value);')
s = s.replace('state.markerPage*PAGE_GENES', 'state.markerPage*pageGenes()').replace('(state.markerPage+1)*PAGE_GENES', '(state.markerPage+1)*pageGenes()')
s = s.replace('genePage*PAGE_GENES', 'genePage*pageGenes()').replace('(genePage+1)*PAGE_GENES', '(genePage+1)*pageGenes()')
s = s.replace('state.markers.length/PAGE_GENES', 'state.markers.length/pageGenes()').replace('${PAGE_GENES}', '${pageGenes()}')
s = s.replace("manifest.shards?.[id]||catalog.shards?.[id]", "manifest.shards?.[id]||catalog.shards?.[id]||mouseCatalog().shards?.[id]")

def replace_function(name, body):
    global s
    pattern = rf'^  (?:async )?function {name}\(.*?(?=^  (?:async )?function |^  const \$ |^  const api=)'
    s, n = re.subn(pattern, lambda _: body.strip('\n') + '\n', s, flags=re.M | re.S)
    assert n == 1, (name, n)

