replace_function('renderDots', r'''
  function renderDots(tool,genePage=state.markerPage,canvasId='dots-'+tool) {
    const geneIds=state.markers.slice(genePage*pageGenes(),(genePage+1)*pageGenes()),rows=dotRows(tool,geneIds);
    if(!active[tool]?.markers){emptyCanvas(canvasId,'Loading existing marker summaries',420);return;}
    if(!geneIds.length){emptyCanvas(canvasId,'Choose markers from the existing panel',420);return;}
    if(!rows.length){emptyCanvas(canvasId,'No produced values for this selection / summary scope',420);return;}
    const labels=[...new Set(rows.map(r=>r.display_label))],layout=global.SATB2_V2.markerLayout(geneIds.length,labels.length,{labelWidth:300,columnWidth:22,rowHeight:26,minWidth:900}),height=layout.height,p=canvasInfo(canvasId,height,layout.width),left=layout.label_width,right=35,top=30,bottom=85;
    const xs=new Map(geneIds.map((g,i)=>[g,left+(i+.5)*(p.width-left-right)/geneIds.length])),ys=new Map(labels.map((l,i)=>[l,top+(i+.5)*(height-top-bottom)/labels.length])),range=markerRange(tool,geneIds),min=range?.[0]??null,max=range?.[1]??null;
    p.c.font='11px system-ui';p.c.textAlign='right';p.c.fillStyle='#304d5f';for(const l of labels)p.c.fillText(l.length>46?l.slice(0,44)+'…':l,left-9,ys.get(l)+4);
    let missing=0;
    for(const r of rows){const g=drawDotValues(r),x=xs.get(r.gene_id),y=ys.get(r.display_label);if(x===undefined)continue;if(!number(g.value)||!range){missing++;p.c.globalAlpha=.65;p.c.strokeStyle='#a9b4bb';p.c.beginPath();p.c.arc(x,y,number(g.area)?Math.sqrt(g.area/Math.PI):2,0,Math.PI*2);p.c.stroke();continue;}if(!number(g.area))continue;p.c.globalAlpha=g.alpha;p.c.fillStyle=continuousColor(g.value,min,max);p.c.beginPath();p.c.arc(x,y,Math.sqrt(g.area/Math.PI),0,Math.PI*2);p.c.fill();}
    p.c.globalAlpha=1;p.c.textAlign='right';p.c.fillStyle='#304d5f';for(const id of geneIds){const gene=manifest.genes.find(g=>g.gene_id===id);p.c.save();p.c.translate(xs.get(id),height-bottom+12);p.c.rotate(-Math.PI/3);p.c.fillText(gene?.gene_symbol||id,0,0);p.c.restore();}
    p.c.textAlign='left';p.c.fillStyle='#657983';p.c.fillText(`${state.markerMetric}: ${fmt(min)} → ${fmt(max)} · ${state.dotRangeMode} color limits · size: detected fraction`,left,14);active[tool].dotRange=range;paintColorKey(p,range);
    if(canvasId==='dots-'+tool)$('dot-note-'+tool).textContent=`${state.markerCondition} summary; ${labels.length} rows / ${geneIds.length} genes on a ${p.width}px wide scrollable plot. ${state.dotRangeMode==='manual'&&!range?'Invalid color limits: minimum must be below maximum. ':''}${state.dotRangeMode} limits ${fmt(min)} to ${fmt(max)}; original values preserved. Negative-z area ×${state.negativeArea}, opacity ${state.negativeAlpha}. ${missing?missing+' unavailable color values (gray outlines). ':''}Custom unions use nucleus-weighted saved summaries. Summary choice does not change a DE fit.`;
  }
''')
