replace_function('renderClusters', r'''
  function renderClusters(tool) {
    const box=$('clusters-'+tool);box.replaceChildren();const ex=excluded(tool),actual=new Map();for(const n of nuclei(tool))actual.set(String(n.cluster_id),(actual.get(String(n.cluster_id))||0)+1);
    for(const row of [...clusterRows(tool)].sort((a,b)=>idSort(a.cluster_id,b.cluster_id))){const id=String(row.cluster_id),n=actual.get(id)||0,r=node('div',undefined,'cluster-row'),check=node('input');check.type='checkbox';check.checked=n>0&&!ex.has(id);check.disabled=!n;check.addEventListener('change',()=>{const set=excluded(tool);check.checked?set.delete(id):set.add(id);state.exclusions[toolKey(tool)]=[...set];selectionChanged();});const main=node('div'),title=node('div','C'+id+' · '+n.toLocaleString()+' baseline nuclei','cluster-title'),input=node('input');input.type='text';input.value=state.labels[clusterKey(tool,id)]||'';input.placeholder=row.reviewed_label||'Custom display label';input.addEventListener('change',()=>{if(input.value.trim())state.labels[clusterKey(tool,id)]=input.value.trim();else delete state.labels[clusterKey(tool,id)];selectionChanged();});main.append(title,input);
      const suggestion=suggestionFor(tool,id),programme=programmeFor(tool,id),select=node('select');select.append(option('','Choose a label suggestion…'),option('__native__','Restore original reviewed label'));
      if(suggestion?.suggested_label)select.append(option(suggestion.suggested_label,'Provisional · '+suggestion.suggested_label));if(suggestion?.parent_label)select.append(option(suggestion.parent_label,'Parent lineage · '+suggestion.parent_label));if(programme)select.append(option(programme.suggested_programme_display_label,'RNA program only · '+programme.suggested_programme_display_label));
      for(const candidate of global.SATB2_V2.labelSuggestions(row))select.append(option(candidate.text,candidate.note+' · '+candidate.text));select.onchange=()=>{if(select.value==='__native__')delete state.labels[clusterKey(tool,id)];else if(select.value)state.labels[clusterKey(tool,id)]=select.value;selectionChanged();};main.append(select);
      const col=node('input');col.type='color';col.value=state.colors[clusterKey(tool,id)]||'#4987a6';col.addEventListener('input',()=>{state.colors[clusterKey(tool,id)]=col.value;touch();});const details=node('div',undefined,'cluster-details');details.append(node('p','Source label: '+(row.reviewed_label||'Unavailable')),node('p',(row.label_confidence||'Review unavailable').replaceAll('_',' ')+' · '+(row.uncertainty_reason||row.exclusion_reason||'Physical position undetermined')));
      if(suggestion){const ev=node('div',undefined,'suggestion-evidence');ev.append(node('b',suggestion.suggested_label||suggestion.parent_label||'Provisional review'),node('p',(suggestion.suggestion_confidence||'Provisional only')+' · fine identity remains uncertain'),node('p','MapMyCells subclass proportions: '+(suggestion.reference_top_subclasses||[]).map(x=>x.label+' '+(100*x.fraction).toFixed(1)+'%').join('; ')),node('p','Parent marker evidence: '+(suggestion.canonical_genes||[]).join(', ')));const show=node('details');show.append(node('summary','Quantitative marker support and caveats'));const quantitative=(suggestion.marker_evidence||[]).filter(x=>x.native_canonical||x.native_conflict_group?.length).slice(0,12).map(x=>({gene:x.gene_symbol,pooled_detected:fmt(x.pooled?.fraction_detected),WT_detected:fmt(x.WT?.fraction_detected),pooled_difference_vs_rest:fmt(x.pooled?.pct_difference_vs_rest),WT_difference_vs_rest:fmt(x.WT?.pct_difference_vs_rest)}));show.append(simpleTable(quantitative,['gene','pooled_detected','WT_detected','pooled_difference_vs_rest','WT_difference_vs_rest'],12));for(const caveat of suggestion.caveats||[])show.append(node('p',caveat));ev.append(show);details.append(ev);}if(programme){const detail=node('details');detail.append(node('summary','CA1 RNA program evidence (separate from identity)'),node('p',programme.suggested_programme_display_label),node('p',`WT expression z: superficial ${fmt(programme.superficial_WT_expression_z)}, deep ${fmt(programme.deep_WT_expression_z)} · ${programme.n_WT_evidence_mice} WT mice · ${programme.n_WT_evidence_nuclei} WT nuclei`),node('p',programme.caveat));details.append(detail);}r.append(check,main,col,details);box.append(r);}
    $('cluster-count-'+tool).textContent=retainedIndices(tool).length.toLocaleString()+' retained / '+nuclei(tool).length.toLocaleString()+' baseline nuclei. Excluded/empty audit groups stay unavailable; edits do not validate identities or change saved memberships.';
  }
''')
replace_function('render', r'''
  function render() {if(headless)return;renderContext();for(const panel of ['umap','markers','de','boxplots','clusters','reliability'])$('tab-'+panel).hidden=state.tab!==panel;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',(b.dataset.category===state.population&&!(state.population==='CA1_ProS'&&state.annotation==='layer_program_label'))||(b.dataset.category==='CA1_programs'&&state.population==='CA1_ProS'&&state.annotation==='layer_program_label')));syncViewControls();if(state.tab==='umap')TOOLS.forEach(renderUMAP);if(state.tab==='clusters')TOOLS.forEach(renderClusters);if(state.tab==='markers'){renderMarkerOptions();$('marker-selected').textContent=state.markers.length+' selected genes; 60–180 genes per page with full-selection PDF and CSV exports.';const pages=Math.max(1,Math.ceil(state.markers.length/pageGenes()));state.markerPage=Math.min(state.markerPage,pages-1);$('marker-page').textContent=`Page ${state.markerPage+1}/${pages} · at most ${pageGenes()} genes`;$('marker-prev').disabled=state.markerPage===0;$('marker-next').disabled=state.markerPage>=pages-1;TOOLS.forEach(t=>renderDots(t));}if(state.tab==='boxplots'){state.boxPage=Math.min(state.boxPage,Math.max(0,Math.ceil(state.boxGenes.length/BOX_PAGE)-1));renderBoxOptions();TOOLS.forEach(t=>{renderTargets(t);const select=$('box-target-'+t);select.replaceChildren(...[...$('de-target-'+t).options].map(o=>option(o.value,o.textContent)));select.value=state.deTargets[t];renderBoxplot(t);});const pages=Math.max(1,Math.ceil(state.boxGenes.length/BOX_PAGE));state.boxPage=Math.min(state.boxPage,pages-1);$('box-page').textContent=`${state.boxGenes.length} selected genes · page ${state.boxPage+1}/${pages} (6 genes per figure)`;$('box-prev').disabled=state.boxPage===0;$('box-next').disabled=state.boxPage>=pages-1;}if(state.tab==='reliability')renderReliability();if(state.tab==='de'){TOOLS.forEach(t=>{renderTargets(t);drawVolcano(t);renderDETable(t);});drawCompare();}}
''')
